import re

def word_crc(word):
    crc = 0
    for char in word:
        crc = (crc << 8) + ord(char)
    return crc

def check_crc(word, crc):
    if word == crc:
        return True
    else:
        return False

def check_password(password):
    word = re.sub(r'[^a-zA-Z0-9]', '', password)
    crc = word_crc(word)
    return check_crc(word, crc)

password = input("Enter your password: ")
if check_password(password):
    print("Password is valid.")
else:
    print("Password is not valid.")
